// Query Classification Function
// Classifies user queries into types and determines if product data is needed

const message = $input.item.json.body.message || '';
const trimmedMessage = message.trim();
const lowerMessage = trimmedMessage.toLowerCase();

// Initialize classification result
const classification = {
  type: 'general',
  needsProductData: false,
  extractedKeywords: [],
  category: null,
  originalMessage: trimmedMessage
};

// Input validation - check for empty or whitespace-only messages
if (!trimmedMessage || trimmedMessage.length === 0) {
  classification.type = 'invalid';
  classification.error = 'EMPTY_INPUT';
  return { json: classification };
}

// Check for messages that are too short (likely invalid)
if (trimmedMessage.length < 2) {
  classification.type = 'invalid';
  classification.error = 'TOO_SHORT';
  return { json: classification };
}

// Price query detection
const priceKeywords = {
  vietnamese: ['giá', 'bao nhiêu', 'giá cả', 'giá bán', 'giá tiền'],
  english: ['price', 'cost', 'how much', 'expensive', 'cheap']
};

const hasPriceKeyword = 
  priceKeywords.vietnamese.some(kw => lowerMessage.includes(kw)) ||
  priceKeywords.english.some(kw => lowerMessage.includes(kw));

if (hasPriceKeyword) {
  classification.type = 'price';
  classification.needsProductData = true;
}

// Suggestion query detection
const suggestionKeywords = {
  vietnamese: ['ăn gì', 'ăn j', 'nấu gì', 'nấu j', 'món gì', 'món j', 'gợi ý', 'đề xuất'],
  english: ['what should i eat', 'what to eat', 'suggest', 'recommend', 'what dish', 'meal idea']
};

const hasSuggestionKeyword = 
  suggestionKeywords.vietnamese.some(kw => lowerMessage.includes(kw)) ||
  suggestionKeywords.english.some(kw => lowerMessage.includes(kw));

if (hasSuggestionKeyword) {
  classification.type = 'suggestion';
  classification.needsProductData = true;
}

// Availability query detection
const availabilityKeywords = {
  vietnamese: ['còn', 'còn không', 'có không', 'có sẵn', 'hết hàng', 'in stock'],
  english: ['available', 'in stock', 'out of stock', 'have', 'do you have']
};

const hasAvailabilityKeyword = 
  availabilityKeywords.vietnamese.some(kw => lowerMessage.includes(kw)) ||
  availabilityKeywords.english.some(kw => lowerMessage.includes(kw));

if (hasAvailabilityKeyword) {
  classification.type = 'availability';
  classification.needsProductData = true;
}

// Extract food-related keywords for product search
const foodKeywords = {
  vegetables: ['rau', 'vegetable', 'cải', 'xà lách', 'cà chua', 'tomato', 'lettuce', 'cabbage'],
  meat: ['thịt', 'meat', 'gà', 'chicken', 'heo', 'pork', 'bò', 'beef'],
  seafood: ['cá', 'fish', 'tôm', 'shrimp', 'mực', 'squid', 'hải sản', 'seafood'],
  fruits: ['trái cây', 'fruit', 'táo', 'apple', 'chuối', 'banana', 'cam', 'orange']
};

const keywords = [];
let detectedCategory = null;

for (const [category, terms] of Object.entries(foodKeywords)) {
  for (const term of terms) {
    if (lowerMessage.includes(term)) {
      keywords.push(term);
      if (!detectedCategory) {
        detectedCategory = category;
      }
    }
  }
}

classification.extractedKeywords = [...new Set(keywords)];
classification.category = detectedCategory;

// Pass through session data
classification.sessionId = $input.item.json.body.sessionId || null;
classification.timestamp = $input.item.json.body.timestamp || Date.now();

return { json: classification };

// System Prompt Builder
// Creates the prompt for Gemini API based on query type and available product data

const inputData = $input.item.json;
const classification = inputData.classification || inputData;
const message = classification.originalMessage;
const queryType = classification.type;
const hasProductError = inputData.productDataError || false;

// Check if we have product data from the Django API
let productData = null;
if (inputData.products) {
  productData = inputData.products;
} else if (inputData.body && inputData.body.products) {
  productData = inputData.body.products;
}

// Base system instructions
const systemInstructions = `You are a helpful food chatbot for a Vietnamese fresh food e-commerce website.

RULES:
1. ONLY answer questions related to food, cooking, recipes, and food products
2. If asked about non-food topics (politics, religion, technology, etc.), politely decline with: "Xin lỗi, tôi chỉ có thể trả lời các câu hỏi về thực phẩm. Bạn có câu hỏi nào về sản phẩm thực phẩm của chúng tôi không?" (Vietnamese) or "Sorry, I can only answer questions about food. Do you have any questions about our food products?" (English)
3. Keep responses concise and helpful (max 3-4 sentences)
4. Use Vietnamese when the user speaks Vietnamese, English when they speak English
5. When suggesting dishes, prefer Vietnamese cuisine
6. Always be polite and friendly`;

// Build the full prompt
let fullPrompt = systemInstructions + '\n\n';

// If product API failed, inform Gemini to apologize and suggest retry
if (hasProductError && (queryType === 'price' || queryType === 'suggestion' || queryType === 'availability')) {
  fullPrompt += 'NOTE: Product data is temporarily unavailable. Apologize to the user and suggest they try again in a moment. ';
}

// Add context based on query type
if (queryType === 'price') {
  fullPrompt += 'The user is asking about product prices. ';
  if (classification.extractedKeywords && classification.extractedKeywords.length > 0) {
    fullPrompt += `They mentioned: ${classification.extractedKeywords.join(', ')}. `;
  }
  if (productData && productData.length > 0) {
    fullPrompt += '\n\nAvailable products:\n';
    productData.slice(0, 5).forEach(p => {
      fullPrompt += `- ${p.name}: ${p.price} ${p.currency}/${p.unit}${p.in_stock ? '' : ' (out of stock)'}\n`;
    });
  }
  fullPrompt += 'Provide helpful information about pricing. ';
} else if (queryType === 'suggestion') {
  fullPrompt += 'The user is asking for food or dish suggestions. ';
  if (productData && productData.length > 0) {
    fullPrompt += '\n\nAvailable products:\n';
    productData.slice(0, 5).forEach(p => {
      fullPrompt += `- ${p.name} (${p.category})\n`;
    });
  }
  fullPrompt += 'Recommend Vietnamese dishes that use fresh ingredients from the available products. ';
} else if (queryType === 'availability') {
  fullPrompt += 'The user is asking about product availability. ';
  if (classification.extractedKeywords && classification.extractedKeywords.length > 0) {
    fullPrompt += `They are interested in: ${classification.extractedKeywords.join(', ')}. `;
  }
  if (productData && productData.length > 0) {
    fullPrompt += '\n\nProduct inventory:\n';
    productData.slice(0, 5).forEach(p => {
      fullPrompt += `- ${p.name}: ${p.in_stock ? 'In stock' : 'Out of stock'}\n`;
    });
  }
} else if (queryType === 'invalid') {
  fullPrompt += 'The user sent an empty or invalid message. Ask them to provide a valid question about food. ';
}

// Add the user's actual query
fullPrompt += `\n\nUser query: ${message}\n\nRespond naturally and helpfully:`;

return {
  json: {
    prompt: fullPrompt,
    queryType: queryType,
    classification: classification,
    productData: productData,
    hasProductError: hasProductError
  }
};

// Gemini API Error Handler
// Handles errors from Gemini API calls including HTTP errors and timeouts

const error = $input.item.json.error || {};
const errorMessage = error.message || '';
const httpCode = error.httpCode || 0;

// Log error details for debugging
const errorLog = {
  timestamp: Date.now(),
  errorType: 'GEMINI_API_ERROR',
  httpCode: httpCode,
  message: errorMessage,
  context: 'Gemini API Request Failed'
};

console.error('Gemini API Error:', JSON.stringify(errorLog));

// Determine specific error type and user message
let userMessage = '';
let errorType = 'UNKNOWN';

if (httpCode === 503) {
  errorType = 'SERVICE_UNAVAILABLE';
  userMessage = 'Xin lỗi, hệ thống AI tạm thời không khả dụng. Vui lòng thử lại sau.';
} else if (httpCode === 401 || httpCode === 403) {
  errorType = 'AUTHENTICATION_ERROR';
  userMessage = 'Xin lỗi, hệ thống đang gặp sự cố xác thực. Vui lòng thử lại sau.';
} else if (httpCode === 429) {
  errorType = 'RATE_LIMIT';
  userMessage = 'Xin lỗi, hệ thống đang quá tải. Vui lòng thử lại sau ít phút.';
} else if (errorMessage.toLowerCase().includes('timeout') || errorMessage.toLowerCase().includes('timed out')) {
  errorType = 'TIMEOUT';
  userMessage = 'Xin lỗi, yêu cầu mất quá nhiều thời gian. Vui lòng thử lại.';
} else {
  errorType = 'GENERAL_ERROR';
  userMessage = 'Xin lỗi, hệ thống tạm thời không khả dụng. Vui lòng thử lại sau.';
}

return {
  json: {
    success: false,
    message: userMessage,
    error: errorType,
    timestamp: Date.now(),
    errorDetails: errorLog
  }
};

// Product API Error Handler
// Handles errors from Django Product API calls including HTTP errors and timeouts

const error = $input.item.json.error || {};
const errorMessage = error.message || '';
const httpCode = error.httpCode || 0;

// Get classification data to pass through
const classification = $input.first().json || {};

// Log error details for debugging
const errorLog = {
  timestamp: Date.now(),
  errorType: 'PRODUCT_API_ERROR',
  httpCode: httpCode,
  message: errorMessage,
  context: 'Django Product API Request Failed',
  queryType: classification.type
};

console.error('Product API Error:', JSON.stringify(errorLog));

// Determine user message
let userMessage = '';
let errorType = 'UNKNOWN';

if (errorMessage.toLowerCase().includes('timeout') || errorMessage.toLowerCase().includes('timed out')) {
  errorType = 'TIMEOUT';
  userMessage = 'Xin lỗi, không thể lấy thông tin sản phẩm lúc này do hết thời gian chờ. Vui lòng thử lại.';
} else if (httpCode >= 500) {
  errorType = 'SERVER_ERROR';
  userMessage = 'Xin lỗi, hệ thống sản phẩm đang gặp sự cố. Vui lòng thử lại sau.';
} else if (httpCode >= 400) {
  errorType = 'CLIENT_ERROR';
  userMessage = 'Xin lỗi, không thể truy xuất thông tin sản phẩm. Vui lòng thử lại.';
} else {
  errorType = 'GENERAL_ERROR';
  userMessage = 'Xin lỗi, không thể lấy thông tin sản phẩm lúc này. Vui lòng thử lại.';
}

// Return classification data without product data so workflow can continue
return {
  json: {
    ...classification,
    productDataError: true,
    productErrorType: errorType,
    productErrorLog: errorLog
  }
};

// Input Validation Handler
// Handles invalid input and returns appropriate error messages

const classification = $input.item.json;
const errorType = classification.error || 'UNKNOWN';

// Log validation error
const errorLog = {
  timestamp: Date.now(),
  errorType: 'VALIDATION_ERROR',
  validationError: errorType,
  message: classification.originalMessage || '',
  context: 'Input Validation Failed'
};

console.error('Input Validation Error:', JSON.stringify(errorLog));

// Determine user message based on error type
let userMessage = '';

if (errorType === 'EMPTY_INPUT') {
  userMessage = 'Vui lòng nhập câu hỏi của bạn về thực phẩm.';
} else if (errorType === 'TOO_SHORT') {
  userMessage = 'Vui lòng nhập câu hỏi đầy đủ hơn về thực phẩm.';
} else {
  userMessage = 'Vui lòng nhập câu hỏi hợp lệ về thực phẩm.';
}

return {
  json: {
    success: false,
    message: userMessage,
    error: 'VALIDATION_ERROR',
    validationError: errorType,
    timestamp: Date.now(),
    errorDetails: errorLog
  }
};

// Gemini Response Validator and Formatter
// Validates and extracts the response from Gemini API, includes product data

const geminiResponse = $input.item.json;
const promptBuilderData = $input.first().json;
const classification = promptBuilderData.classification;
const productData = promptBuilderData.productData;

// Initialize result
const result = {
  success: false,
  message: '',
  products: [],
  queryType: classification.type,
  timestamp: classification.timestamp || Date.now(),
  sessionId: classification.sessionId,
  error: null
};

try {
  // Validate response structure
  if (!geminiResponse || typeof geminiResponse !== 'object') {
    throw new Error('Invalid response format: response is not an object');
  }

  if (!geminiResponse.candidates || !Array.isArray(geminiResponse.candidates)) {
    throw new Error('Invalid response format: missing candidates array');
  }

  if (geminiResponse.candidates.length === 0) {
    throw new Error('Invalid response format: candidates array is empty');
  }

  const candidate = geminiResponse.candidates[0];

  if (!candidate.content) {
    throw new Error('Invalid response format: missing content in candidate');
  }

  if (!candidate.content.parts || !Array.isArray(candidate.content.parts)) {
    throw new Error('Invalid response format: missing parts array in content');
  }

  if (candidate.content.parts.length === 0) {
    throw new Error('Invalid response format: parts array is empty');
  }

  const textPart = candidate.content.parts[0];

  if (!textPart.text || typeof textPart.text !== 'string') {
    throw new Error('Invalid response format: missing or invalid text in parts');
  }

  // Extract the text response
  const responseText = textPart.text.trim();

  if (responseText.length === 0) {
    throw new Error('Invalid response: empty text response');
  }

  // Success - valid response
  result.success = true;
  result.message = responseText;

  // Format product data based on query type
  if (productData && Array.isArray(productData) && productData.length > 0) {
    if (classification.type === 'price') {
      // Include price information
      result.products = productData.slice(0, 5).map(p => ({
        name: p.name,
        price: `${p.price.toLocaleString()} ${p.currency}/${p.unit}`,
        available: p.in_stock
      }));
    } else if (classification.type === 'suggestion') {
      // Include product names and categories for suggestions
      result.products = productData.slice(0, 3).map(p => ({
        name: p.name,
        category: p.category
      }));
    } else if (classification.type === 'availability') {
      // Include availability status
      result.products = productData.slice(0, 5).map(p => ({
        name: p.name,
        available: p.in_stock
      }));
    }
  }

} catch (error) {
  // Handle validation errors
  result.success = false;
  result.error = error.message;
  result.message = 'Xin lỗi, hệ thống tạm thời không khả dụng. Vui lòng thử lại sau.';

  // Log error for debugging
  console.error('Gemini Response Validation Error:', {
    error: error.message,
    response: geminiResponse,
    timestamp: result.timestamp
  });
}

return { json: result };
